import { existsSync, readFileSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { fail, note, ok } from "./lib.mjs";

// @adr 001 - orchestration support: materialize the parts the manifest names
//
// Support script, NOT a gate (registered notAGate). DRY by default: it PRINTS
// the command that would materialize each absent part and touches nothing.
// `--exec` clones the parts that declare a `repo` URL; parts without one are
// GENERATED by the proto-forge skill (T14: backend first — the contract must
// exist before its consumers — then frontend, then e2e), which no script can
// run on the operator's behalf, so those stay printed instructions either way.

const exec = process.argv.includes("--exec");
const write = (s) => process.stdout.write(`${s}\n`);

if (!existsSync("workspace.json")) fail("ws-bootstrap: workspace.json is missing");
let manifest;
try {
  manifest = JSON.parse(readFileSync("workspace.json", "utf8"));
} catch (e) {
  fail(`ws-bootstrap: workspace.json does not parse: ${e.message}`);
}
const parts = Array.isArray(manifest.parts) ? manifest.parts : [];

// Manifest order IS generation order (T14): the generator writes parts[]
// backend → frontend → e2e, so walking it in order preserves the contract-first
// discipline without re-deriving it here.
let absent = 0;
for (const p of parts) {
  if (typeof p.dir === "string" && existsSync(p.dir)) {
    write(`# ${p.dir}/ already present (part "${p.id}") — nothing to do`);
    continue;
  }
  absent += 1;
  if (typeof p.repo === "string" && p.repo !== "") {
    if (exec) {
      note(`cloning part "${p.id}" from ${p.repo}`);
      const r = spawnSync("git", ["clone", p.repo, p.dir], { stdio: "inherit" });
      if (r.status !== 0) fail(`ws-bootstrap: git clone failed for part "${p.id}" (${p.repo})`);
    } else {
      write(`git clone ${p.repo} ${p.dir}`);
    }
  } else {
    write(`# part "${p.id}": generate ${p.dir}/ from the proto-forge template "${p.template}"`);
    write(`#   run the proto-forge skill with this workspace's shared brief (.prompts/0002-brief.md);`);
    write(`#   the generated facets.json must record pairedBrief ${manifest.pairedBrief}`);
  }
}

if (absent === 0) ok("ws-bootstrap: every part directory is present");
else if (!exec) note(`dry run — ${absent} part(s) absent; re-run with --exec to clone the parts that declare a repo URL`);
else ok("ws-bootstrap: done — parts without a repo URL still need generation (see the printed instructions)");
